bash.command:
# 103-final-main-audit
set -eo pipefail
layerfs() { node "$DSH_LAYERFS_CLI" "$@"; }
. "{{scenario}}/../shared/replay.sh"
ws=$(kept ws-root-workspaces-12)   # mounted by an earlier step as /workspaces/12
code=0; layerfs workspace exec "$ws" -m 'final source, binary and child lifecycle audit' --stream -- 'timeout 30 python3 - <<'\''AUDIT'\''
from pathlib import Path
import json,os,hashlib,stat,subprocess
sources={}
for path in Path('\''crates'\'').glob('\''*/src/**/*.rs'\''):
 lines=len(path.read_text().splitlines());assert lines<=999,(str(path),lines)
 if path.name in ['\''lib.rs'\'','\''mod.rs'\'']:assert lines<=200,(str(path),lines)
 sources[str(path)]=lines
binaries={}
for name in ['\''depot-server'\'','\''depot-cli'\'']:
 p=Path('\''target/debug'\'')/name;h=hashlib.sha256()
 with p.open('\''rb'\'') as f:
  while b:=f.read(65536):h.update(b)
 assert os.access(p,os.X_OK)
 binaries[name]={'\''bytes'\'':p.stat().st_size,'\''mode'\'':oct(stat.S_IMODE(p.stat().st_mode)),'\''sha256'\'':h.hexdigest()}
live=[];zombies=[]
for p in Path('\''/proc'\'').iterdir():
 if not p.name.isdigit():continue
 try:
  name=(p/'\''comm'\'').read_text().strip();state=(p/'\''stat'\'').read_text().split('\'') '\'',1)[1].split()[0]
  if name in ['\''depot-server'\'','\''depot-cli'\'','\''chromedriver'\'','\''chromium'\'']:(zombies if state=='\''Z'\'' else live).append({'\''pid'\'':p.name,'\''name'\'':name,'\''state'\'':state})
 except (OSError,IndexError):pass
assert not live,live
env={**os.environ,'\''CARGO_HOME'\'':str(Path('\''.cargo-home'\'').resolve()),'\''CARGO_TARGET_DIR'\'':str(Path('\''target'\'').resolve()),'\''RUSTUP_HOME'\'':'\''/usr/local/rustup'\'','\''RUSTC_WRAPPER'\'':'\'''\'','\''RUSTC_WORKSPACE_WRAPPER'\'':'\'''\''}
r=subprocess.run(['\''timeout'\'','\''20'\'','\''cargo'\'','\''metadata'\'','\''--locked'\'','\''--offline'\'','\''--no-deps'\'','\''--format-version'\'','\''1'\''],env=env,capture_output=True,text=True,timeout=22);assert r.returncode==0,r.stderr
metadata=json.loads(r.stdout)
docs={p['\''name'\'']:[t['\''kind'\''] for t in p['\''targets'\'']] for p in metadata['\''packages'\'']}
versions={tool:subprocess.run(['\''timeout'\'','\''5'\'',tool,'\''--version'\''],capture_output=True,text=True,timeout=6).stdout.strip() for tool in ['\''rustc'\'','\''cargo'\'','\''chromium'\'','\''chromedriver'\'']}
print(json.dumps({'\''source_physical_lines'\'':sources,'\''retained_binaries'\'':binaries,'\''live_application_browser_processes'\'':live,'\''reaped_or_inert_zombies'\'':zombies,'\''package_target_kinds'\'':docs,'\''versions'\'':versions},sort_keys=True))
AUDIT' || code=$?
exit_is "$code" 0
layerfs workspace commit "$ws" -m 'final-main acceptance source/binary/process audit (exit 0)' | kind Committed UpToDate
